private fun readLn() = readLine()!!
private fun readInt() = readLn().toInt()
private fun readStrings() = readLn().split(" ") 
private fun readInts() = readStrings().map{it.toInt()} 

fun main() {
  val (n, MOD) = readInts()
  fun add (x : Long, y : Long) : Long = if (x + y < MOD) x + y else x + y - MOD
  fun sub (x : Long, y : Long) : Long = if (x < y) x - y + MOD else x - y
  val DP = Array<LongArray>(n + 1){LongArray(0){0}}
  DP[0] = LongArray(1){1}
  for (i in 1..n) {
    val dim = i * (i - 1) / 2
    DP[i] = LongArray(dim + 1){0}
    var sum = 0L
    for (j in 0..dim) {
      if (j < DP[i - 1].size) sum = add(sum, DP[i - 1][j])
      DP[i][j] = sum
      if (j >= i - 1) sum = sub(sum, DP[i - 1][j - i + 1])
    }
  }
  val pf = LongArray(n * n){0}
  var ans = 0L
  for (cut in 2 until n) {
    val dim = cut * (cut - 1) / 2
    for (i in 1..dim) pf[i] = add(pf[i - 1], DP[cut][i])
    fun range (l : Int, r : Int) : Long {
      if (l > minOf(r, dim)) return 0L
      return sub(pf[minOf(r, dim)], if (l > 0) pf[l - 1] else 0)
    }
    var (tot, aux, sum) = arrayOf(0L, 0L, 0L)
    for (x in dim downTo 0) {
      val yo = (range(x + cut + 1, dim) * (cut * (cut + 1) / 2) + sum) % MOD
      tot = add(tot, DP[cut][x] * yo % MOD)
      if (x + cut <= dim) sum = sub(sum, DP[cut][x + cut] * (cut * (cut + 1) / 2 - 1) % MOD)
      sum = add(sum, aux)
      if (x + cut - 1 <= dim) aux = sub(aux, DP[cut][x + cut - 1] * 2 % MOD)
      aux = add(aux, DP[cut][x] * (cut + 1) % MOD)
      aux = sub(aux, range(x, x + cut - 2))
    }
    for (i in (cut + 2)..n) tot = tot * i % MOD
    ans = add(ans, tot)
  }
  println(ans)
}
